fn close_remaining(policy:RetainedCloneGrant,spent:RetainedCloneProgress)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:policy.maximum_items.checked_sub(spent.copied_items).unwrap(),maximum_copy_bytes:policy.maximum_copy_bytes.checked_sub(spent.copied_bytes).unwrap(),maximum_capacity_bytes:policy.maximum_capacity_bytes.checked_sub(spent.retained_capacity_bytes).unwrap(),maximum_release_bytes:policy.maximum_release_bytes.checked_sub(spent.released_bytes).unwrap(),maximum_depth:policy.maximum_depth}}
fn close<T:semio_framework_value::retirement::RetireOwned+'static>(output:T)->(usize,usize){let c=contract();let policy=grant();let(mut owner,heap)=observe(||semio_framework_value::retirement::controlled::ControlledRetirement::new(output).ok().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut spent=RetainedCloneProgress::default();for _ in 0..c["maximumCloseTurns"].as_u64().unwrap(){let original=owner.original().map(|value|value as*const T);let(zero,heap)=observe(||owner.step(Default::default()).unwrap());assert_eq!((zero.progress(),heap.requested_bytes,heap.released_bytes),(Default::default(),0,0));assert_eq!(owner.original().map(|value|value as*const T),original);if owner.terminal_is_empty(){break}let allowance=close_remaining(policy,spent);let(step,heap)=observe(||owner.step(allowance).unwrap());let progress=step.progress();assert!(progress.fits(allowance));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));spent=spent.checked_add(progress).unwrap();assert!(spent.fits(policy));assert!(progress!=Default::default()||owner.terminal_is_empty());}assert!(owner.terminal_is_empty());let(terminal,heap)=observe(||owner.step(Default::default()).unwrap());assert_eq!((terminal.progress(),heap.requested_bytes,heap.released_bytes),(Default::default(),0,0));let(_,heap)=observe(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));(spent.retained_capacity_bytes,spent.released_bytes)}
fn ready_file<T>(future:impl std::future::Future<Output=T>)->T{let mut future=std::pin::pin!(future);let mut context=std::task::Context::from_waker(std::task::Waker::noop());match std::future::Future::poll(future.as_mut(),&mut context){std::task::Poll::Ready(value)=>value,std::task::Poll::Pending=>panic!("original synchronous SQLite receiver must be ready")}}
macro_rules! original{
 ($name:ident,$native:ident,$owner:ident,$recipient:path,$progress:path)=>{
 fn $name<T:semio_framework_value::retirement::RetireOwned+'static>(policy:RetainedCloneGrant,target:usize,mode:u8,operation:impl FnOnce(&mut SqliteSnapshotControl<'_>,&mut $owner<'_,'_>,&AtomicBool)->Result<T,ValueError>)->(Result<T,ValueError>,usize,usize){
  let c=contract();let closing=grant();let native_live=AtomicBool::new(true);let sql_live=AtomicBool::new(true);let cut=AtomicBool::new(false);let body_completed=AtomicBool::new(false);let mut observer=|_|{if matches!(mode,4|6)&&body_completed.load(Ordering::Relaxed){cut.store(true,Ordering::Relaxed);native_live.store(false,Ordering::Relaxed);}native_live.load(Ordering::Relaxed)};let mut recipient=<$recipient>::new();let mut native=semio_framework_value::$native::new(c["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|event:SqliteSnapshotProgress|{if !sql_live.load(Ordering::Relaxed){return false}if matches!(mode,3|5)&&body_completed.load(Ordering::Relaxed){cut.store(true,Ordering::Relaxed);sql_live.store(false,Ordering::Relaxed);return false}if mode>0&&target>=512&&event.total==target&&event.completed>=256{cut.store(true,Ordering::Relaxed);if mode==1{sql_live.store(false,Ordering::Relaxed);return false}native_live.store(false,Ordering::Relaxed);}true};let mut sql=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:c["sqlMaximumBytes"].as_u64().unwrap()as usize,..Default::default()});let remaining=sql.allocation_remaining_bytes();let mut owner=$owner::new(&mut native,policy);let original_cause=if matches!(mode,3|5){body_completed.store(true,Ordering::Relaxed);let cause=sql.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).unwrap_err();body_completed.store(false,Ordering::Relaxed);Some(cause)}else if matches!(mode,4|6){body_completed.store(true,Ordering::Relaxed);let cause=owner.native().checkpoint().unwrap_err();body_completed.store(false,Ordering::Relaxed);native_live.store(true,Ordering::Relaxed);Some(cause)}else if mode==1{Some(sql.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,256,target).unwrap_err())}else if mode==2{native_live.store(false,Ordering::Relaxed);let error=owner.native().checkpoint().unwrap_err();native_live.store(true,Ordering::Relaxed);Some(error)}else{None};sql_live.store(true,Ordering::Relaxed);cut.store(false,Ordering::Relaxed);
  let(result,heap)=observe(||operation(&mut sql,&mut owner,&body_completed));let progress=owner.progress();if let Err(error)=&result{assert_eq!(error.retained_progress(),progress)}assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));drop(owner);assert_eq!(remaining-sql.allocation_remaining_bytes(),native.owned_bytes());let(mut born,mut released)=(heap.requested_bytes,heap.released_bytes);let mut close_spent=RetainedCloneProgress::default();
  if mode>0{if mode<5{assert!(cut.load(Ordering::Relaxed));}else{assert!(body_completed.load(Ordering::Relaxed));}let error=result.as_ref().err().unwrap();assert_eq!(error.kind,if mode<5{ValueRefusalKind::Canceled}else{ValueRefusalKind::InvalidValue});assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));let expected=if mode<5{original_cause.as_ref().unwrap().message.as_ref()}else{FAILED_BODY};assert_eq!(error.message,expected);assert_eq!(error.message.as_ptr(),expected.as_ptr());assert_eq!(heap.released_bytes,0);assert!(native.has_retirement_owner());let before=native.owned_bytes();let sql_before=sql.allocation_remaining_bytes();let mut observe_sql=|event:$progress|sql.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,event.completed,event.total).is_ok();let(probe,heap)=observe(||native.scoped_observer(&mut observe_sql,|native|native.close_retirement_recipient(closing)));assert_eq!(probe.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(native.owned_bytes(),before);assert_eq!(sql.allocation_remaining_bytes(),sql_before);}
  native_live.store(true,Ordering::Relaxed);sql_live.store(true,Ordering::Relaxed);body_completed.store(false,Ordering::Relaxed);let baseline=native.owned_bytes();let settlement=semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::ReceivingSettlement::new(&mut sql,baseline,SqliteSnapshotPhase::ProjectSnapshot);settlement.finish_body(baseline).unwrap();let mut observe_sql=|event:$progress|settlement.observe(event.owned_bytes,event.completed,event.total);let(zero,heap)=observe(||native.scoped_observer(&mut observe_sql,|native|native.close_retirement_recipient(Default::default())).unwrap());assert_eq!((zero.progress(),heap.requested_bytes,heap.released_bytes),(RetainedCloneProgress::default(),0,0));
  for _ in 0..c["maximumCloseTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(step,heap)=observe(||native.scoped_observer(&mut observe_sql,|native|native.close_retirement_recipient(close_remaining(closing,close_spent))).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;close_spent=close_spent.checked_add(step.progress()).unwrap();assert!(close_spent.fits(closing));}assert!(!native.has_retirement_owner());settlement.finish_body(native.owned_bytes()).unwrap();drop(observe_sql);drop(settlement);assert_eq!(remaining-sql.allocation_remaining_bytes(),native.owned_bytes());eprintln!("[DEBUG] EPW {} mode={mode} originalSQLNative=true receipt={progress:?} actualBorn={born} actualReleased={released}",stringify!($name));(result,born,released)
 }
 };
}
