fn independent(database:&SqliteDatabase,sql:&str,valid:bool)->SqliteDatabase{
 use std::{io::Write,process::{Command,Stdio}};let bytes=export_sqlite_database(database,Default::default(),&mut |_|true).unwrap();let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));d.run('PRAGMA foreign_keys=OFF');d.run('PRAGMA ignore_check_constraints=ON');if(process.argv.at(-2).trim())d.run(process.argv.at(-2));if(process.argv.at(-1)==='true'&&(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length))throw Error('EPW independent relations');await Bun.write(Bun.stdout,d.serialize());d.close();"#;let mut child=Command::new("bun").args(["-e",script,"--",sql,if valid{"true"}else{"false"}]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));import_sqlite_database(&output.stdout,Default::default(),&mut |_|true).unwrap()
}
