#[test]
fn sqlite_snapshot_epw_original_receiving_cumulative(){
 let input=source("complete");let database=database(&input);let coordinate=dialect();macro_rules! prior{($native:ident,$owner:ident,$recipient:path,$method:ident)=>{{let c=contract();let mut callback=|_|true;let mut native=semio_framework_value::$native::new(c["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);let mut recipient=<$recipient>::new();native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut sql=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:c["sqlMaximumBytes"].as_u64().unwrap()as usize,..Default::default()});let(seed,seed_heap)=observe(||native.allocate_vec::<u8>(c["priorBaseline"]["nativeBytes"].as_u64().unwrap()as usize).unwrap());assert_eq!((seed_heap.requested_bytes,seed_heap.released_bytes),(c["priorBaseline"]["nativeBytes"].as_u64().unwrap()as usize,0));let seed_pointer=seed.as_ptr();sql.admit_native_allocation_bytes(c["priorBaseline"]["sqlBytes"].as_u64().unwrap()as usize).unwrap();let native_before=native.owned_bytes();assert_eq!(native_before,seed.capacity());let remaining=sql.allocation_remaining_bytes();let mut owner=$owner::new(&mut native,grant());let(result,heap)=observe(||input.$method(&coordinate,&database,&mut sql,&mut owner));result.unwrap();let first=owner.progress();assert!(first.retained_capacity_bytes>0&&first.released_bytes>0);assert_eq!((heap.requested_bytes,heap.released_bytes),(first.retained_capacity_bytes,first.released_bytes));let(result,heap)=observe(||input.$method(&coordinate,&database,&mut sql,&mut owner));result.unwrap();let total=owner.progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(total.retained_capacity_bytes-first.retained_capacity_bytes,total.released_bytes-first.released_bytes));
  for axis in 0..3{let mut wrong=dialect();match axis{0=>wrong.artifact_kind="wrong".into(),1=>wrong.standard="wrong".into(),_=>wrong.subset="wrong".into()}let(result,heap)=observe(||input.$method(&wrong,&database,&mut sql,&mut owner));let error=result.unwrap_err();assert_eq!(error.cause.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.cause.message,"EPW owned SQLite dialect differs");assert_eq!(error.cause.retained_progress(),owner.progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}drop(owner);assert!(!native.has_retirement_owner());assert_eq!(remaining-sql.allocation_remaining_bytes(),native.owned_bytes()-native_before);assert_eq!(seed.as_ptr(),seed_pointer);let(born,released)=close(seed);assert_eq!(native_before+born,released);}};}
 prior!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeRetirementRecipient,validate_sqlite_snapshot_subset_decoding);prior!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,validate_sqlite_snapshot_subset_encoding);
 eprintln!("[DEBUG] EPW exact dialect refusals and prior cumulative receipts preserve actual zero heap and original ledgers");
}
#[test]
fn sqlite_snapshot_epw_original_receiving_prepublication_cancellation(){
 let input=source("complete");let database=database(&input);let c=contract();assert_eq!(c["prepublication"]["publicationCalls"],0);for mode in[3,4,5,6]{for operation in 0..4{let published=AtomicBool::new(false);let(result,born,released)=match operation{
 0=>decode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::project(&input,frame,port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())})),
 1=>encode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::read(&database,frame,None,port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())})),
 2=>decode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::read(&database,frame,Some(&input),port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())})),
 _=>encode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::read(&database,frame,Some(&input),port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())}))
 };assert!(!published.load(Ordering::Relaxed),"original body cancellation must precede domain status take and publication");assert_eq!(result.unwrap_err().kind,if mode<5{ValueRefusalKind::Canceled}else{ValueRefusalKind::InvalidValue});assert_eq!(born,released);}}
 eprintln!("[DEBUG] EPW all4 complete-or-failed bodies/2 original cancellation kinds retain status before domain publication, preserve exact original causes and finite same recipient paid physical close");
}
